import type { FilterCondition } from "@adistack/data-explorer";
import {
	createFilter,
	getDefaultOperator,
	useDataExplorerContext,
	validateCondition,
} from "@adistack/data-explorer";
import { IconDeviceFloppy, IconPencil, IconPlus } from "@tabler/icons-react";
import { AnimatePresence, m, useReducedMotion } from "motion/react";
import { useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { SentenceBuilderRow } from "./builder-row.tsx";
import { SentenceView } from "./sentence-view.tsx";

/** Shared-layout glide — mirrors recruiter-mg `beui/ease` SPRING_LAYOUT. */
const SPRING_LAYOUT = {
	damping: 32,
	mass: 0.6,
	stiffness: 360,
	type: "spring",
} as const;

const MotionButton = m.create(Button);

interface FilterSentenceProps {
	className?: string;
	/** Prose subject, e.g. "Employees". Default "records". */
	subject?: string;
}

/**
 * Saved filters rendered as a plain-language sentence that morphs in place
 * into a Where/And/Or builder. Reads `table.state.dataFilters` via the
 * DataExplorer context; Edit snapshots the committed filters into a local
 * draft, and Save validates every row (`validateCondition`) before committing
 * atomically with `table.setDataFilters(draft)`. Leaving without Save is an
 * implicit discard. Requires a DataExplorer Provider ancestor.
 */
export function FilterSentence({
	className,
	subject = "records",
}: FilterSentenceProps): React.JSX.Element {
	const { columnsConfig, table } = useDataExplorerContext();
	const [advanced, setAdvanced] = useState(false);
	const [draft, setDraft] = useState<FilterCondition[]>([]);

	const reduce = useReducedMotion();
	const motionSafe = reduce ? ({ duration: 0 } as const) : SPRING_LAYOUT;
	const panelMotion = {
		animate: { opacity: 1, scale: 1, y: 0 },
		exit: { opacity: 0, scale: 0.98, y: -12 },
		initial: { opacity: 0, scale: 0.98, y: 12 },
		transition: motionSafe,
	} as const;
	const rowMotion = {
		animate: { opacity: 1, x: 0 },
		exit: { opacity: 0, transition: { duration: 0.15 }, x: -16 },
		initial: { opacity: 0, x: -16 },
		transition: motionSafe,
	} as const;

	const columnsById = useMemo(
		() => new Map(columnsConfig.map((column) => [column.id, column])),
		[columnsConfig],
	);
	const rowError = (condition: FilterCondition) =>
		validateCondition(condition, columnsById);
	const canSave = draft.every((condition) => rowError(condition) === undefined);

	const openBuilder = () => {
		// Snapshot the committed filters so leaving without Save never touches
		// `table.state`; ids are preserved so row keys stay stable.
		setDraft(table.state.dataFilters.map((condition) => ({ ...condition })));
		setAdvanced(true);
	};

	const save = () => {
		table.setDataFilters(draft);
		setAdvanced(false);
	};

	const patchCondition = (id: string, patch: Partial<FilterCondition>): void =>
		setDraft((previous) =>
			previous.map((condition) =>
				condition.id === id ? { ...condition, ...patch } : condition,
			),
		);

	const removeCondition = (id: string): void =>
		setDraft((previous) =>
			previous
				.filter((condition) => condition.id !== id)
				.map((condition, index) =>
					index === 0 && condition.combinator !== "and"
						? { ...condition, combinator: "and" }
						: condition,
				),
		);

	const addCondition = (): void => {
		const column = columnsConfig[0];
		if (!column) return;
		setDraft((previous) => [
			...previous,
			createFilter(column.id, getDefaultOperator(column.type), ""),
		]);
	};

	return (
		<m.div
			className={cn(
				"overflow-hidden rounded-lg border border-input bg-card shadow-xs",
				className,
			)}
			layout
			transition={motionSafe}
		>
			<AnimatePresence initial={false} mode="popLayout">
				{advanced ? (
					<m.div className="space-y-1.5 p-3" key="builder" {...panelMotion}>
						<AnimatePresence initial={false}>
							{draft.map((condition, index) => (
								<m.div key={condition.id} layout {...rowMotion}>
									<SentenceBuilderRow
										column={columnsById.get(condition.columnId)}
										columns={columnsConfig}
										condition={condition}
										error={rowError(condition)}
										index={index}
										onPatch={patchCondition}
										onRemove={removeCondition}
									/>
								</m.div>
							))}
						</AnimatePresence>
						<div className="flex items-center gap-2 pt-1">
							<span className="w-14" />
							<Button
								className="h-7 rounded-md border border-dashed border-border bg-transparent text-xs text-muted-foreground shadow-none hover:border-foreground/30 hover:text-foreground"
								onClick={addCondition}
								size="sm"
								variant="outline"
							>
								<IconPlus aria-hidden="true" className="size-3" />
								Add condition
							</Button>
							<MotionButton
								className="ml-auto shrink-0"
								disabled={!canSave}
								layoutId="filter-sentence-action"
								onClick={save}
								size="sm"
								variant="outline"
							>
								<IconDeviceFloppy aria-hidden="true" />
								Save
							</MotionButton>
						</div>
					</m.div>
				) : (
					<m.div
						className="flex flex-wrap items-center justify-between gap-2 px-3 py-2.5"
						key="sentence"
						{...panelMotion}
					>
						<SentenceView
							columnsConfig={columnsConfig}
							conditions={table.state.dataFilters}
							subject={subject}
						/>
						<MotionButton
							className="ml-auto shrink-0"
							layoutId="filter-sentence-action"
							onClick={openBuilder}
							size="sm"
							variant="outline"
						>
							<IconPencil aria-hidden="true" />
							Edit
						</MotionButton>
					</m.div>
				)}
			</AnimatePresence>
		</m.div>
	);
}

import type { ColumnConfig, FilterCondition } from "@adistack/data-explorer";
import {
	formatFilterValue,
	getOperatorArity,
	getOperatorLabel,
} from "@adistack/data-explorer";

import { cn } from "@/lib/utils";

interface SentenceViewProps {
	columnsConfig: ColumnConfig[];
	conditions: FilterCondition[];
	/** Prose subject, e.g. "Employees". Default "records". */
	subject: string;
}

function Term({
	children,
	className,
}: {
	children: React.ReactNode;
	className?: string;
}): React.JSX.Element {
	return (
		<span
			className={cn(
				"rounded bg-muted/80 px-1.5 py-0.5 font-medium text-foreground",
				className,
			)}
		>
			{children}
		</span>
	);
}

/**
 * Prose rendering of committed filters: "Tasks whose <status> <is> <todo>
 * and <priority> <is> <high>". A faithful view of `table.state.dataFilters` —
 * unknown columns and stale conditions render degraded (raw id, muted chip),
 * never filtered out or thrown on.
 */
export function SentenceView({
	columnsConfig,
	conditions,
	subject,
}: SentenceViewProps): React.JSX.Element {
	return (
		<p className="flex flex-wrap items-center gap-x-1.5 gap-y-1 text-sm leading-relaxed text-muted-foreground">
			{conditions.length === 0 ? (
				<span className="italic">
					No conditions yet — pick Edit to add one.
				</span>
			) : (
				<>
					<span>{subject}</span>
					{conditions.map((condition, index) => {
						const column = columnsConfig.find(
							(candidate) => candidate.id === condition.columnId,
						);
						const displayValue = formatFilterValue(
							condition.value,
							condition.operator,
							column ?? { type: "string" },
						);
						return (
							<span
								className="inline-flex items-center gap-1 whitespace-nowrap"
								key={condition.id}
							>
								{index === 0 ? "whose" : condition.combinator}
								<Term className={column ? undefined : "text-muted-foreground"}>
									{column ? column.displayName : condition.columnId}
								</Term>
								<Term>{getOperatorLabel(condition.operator)}</Term>
								{displayValue !== null ? (
									<Term>{displayValue}</Term>
								) : getOperatorArity(condition.operator) ===
									"nullary" ? null : (
									<Term className="font-normal text-muted-foreground italic">
										any value
									</Term>
								)}
							</span>
						);
					})}
				</>
			)}
		</p>
	);
}

import type {
	ColumnConfig,
	ConditionValidationError,
	FilterCondition,
	FilterOperator,
} from "@adistack/data-explorer";
import {
	coerceFilterValue,
	getDefaultOperator,
	getOperatorLabel,
	getOperatorsForType,
} from "@adistack/data-explorer";
import { IconX } from "@tabler/icons-react";

import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { ValueInput } from "../filter-input/value-input.tsx";

interface SentenceBuilderRowProps {
	/** Column resolved from the condition (undefined for stale/unknown ids). */
	column: ColumnConfig | undefined;
	columns: ColumnConfig[];
	condition: FilterCondition;
	/** Validation failure for this row, computed once by `FilterSentence`. */
	error: ConditionValidationError | undefined;
	index: number;
	onPatch: (id: string, patch: Partial<FilterCondition>) => void;
	onRemove: (id: string) => void;
}

/**
 * One builder row: Where/And/Or connector, column + operator selects, value
 * editor, remove button. Edits stay local to the draft — commit happens only
 * on Save in `FilterSentence`.
 */
export function SentenceBuilderRow({
	column,
	columns,
	condition,
	error,
	index,
	onPatch,
	onRemove,
}: SentenceBuilderRowProps): React.JSX.Element {
	const operators = column
		? (column.operators ?? getOperatorsForType(column.type))
		: [];

	const handleColumnChange = (columnId: string): void => {
		const nextColumn = columns.find((candidate) => candidate.id === columnId);
		if (!nextColumn) return;
		const nextOperators =
			nextColumn.operators ?? getOperatorsForType(nextColumn.type);
		onPatch(
			condition.id,
			nextOperators.includes(condition.operator)
				? { columnId }
				: { columnId, operator: getDefaultOperator(nextColumn.type) },
		);
	};

	const handleOperatorChange = (operator: FilterOperator): void => {
		const { value } = coerceFilterValue(operator, condition.value);
		onPatch(condition.id, { operator, value });
	};

	return (
		<div
			aria-invalid={error ? true : undefined}
			className={cn(
				"flex flex-wrap items-center gap-2 rounded-md",
				error && "ring-1 ring-destructive/50",
			)}
			title={error?.message}
		>
			{index === 0 ? (
				<span
					className="w-14 text-right text-xs text-muted-foreground"
					title="First condition"
				>
					Where
				</span>
			) : (
				<button
					className={cn(
						"w-14 text-right text-xs",
						condition.combinator === "and"
							? "text-muted-foreground"
							: "text-primary hover:underline",
					)}
					onClick={() =>
						onPatch(condition.id, {
							combinator: condition.combinator === "and" ? "or" : "and",
						})
					}
					title="Toggle And / Or"
					type="button"
				>
					{condition.combinator === "and" ? "And" : "Or"}
				</button>
			)}
			<Select onValueChange={handleColumnChange} value={condition.columnId}>
				<SelectTrigger aria-label="Filter column" className="h-7 w-36 text-xs">
					<SelectValue placeholder="Field" />
				</SelectTrigger>
				<SelectContent className="min-w-36">
					{columns.map((candidate) => (
						<SelectItem key={candidate.id} value={candidate.id}>
							{candidate.displayName}
						</SelectItem>
					))}
				</SelectContent>
			</Select>
			<Select onValueChange={handleOperatorChange} value={condition.operator}>
				<SelectTrigger
					aria-label="Filter operator"
					className="h-7 w-36 text-xs"
				>
					<SelectValue placeholder="Operator" />
				</SelectTrigger>
				<SelectContent className="min-w-36">
					{operators.map((operator) => (
						<SelectItem key={operator} value={operator}>
							{getOperatorLabel(operator)}
						</SelectItem>
					))}
				</SelectContent>
			</Select>
			{column ? (
				<div className="min-w-36 flex-1">
					<ValueInput
						column={column}
						onChange={(value) => onPatch(condition.id, { value })}
						onCommit={() => {}}
						operator={condition.operator}
						value={condition.value}
					/>
				</div>
			) : (
				<span className="flex-1 text-muted-foreground text-xs">
					Unknown column
				</span>
			)}
			<button
				aria-label="Remove condition"
				className="flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
				onClick={() => onRemove(condition.id)}
				type="button"
			>
				<IconX aria-hidden="true" className="size-3.5" />
			</button>
		</div>
	);
}
